import importlib
import shutil
import subprocess
import sys

available = {}
for mod in ["pypdf", "PyPDF2", "fitz", "pdfplumber", "reportlab"]:
    try:
        importlib.import_module(mod)
        available[mod] = True
    except ImportError:
        available[mod] = False

for tool in ["qpdf", "pdftk", "gs", "pdfunite", "pdftotext"]:
    available[tool] = shutil.which(tool) is not None

for name, ok in available.items():
    print(f"{name}: {'available' if ok else 'missing'}")

import re

OBJ_RE = re.compile(rb"(\d+)\s+0\s+obj\b(.*?)endobj", re.DOTALL)
REF_RE = re.compile(rb"(\d+)\s+0\s+R")
DICT_REF_RE = re.compile(rb"/\w+\s+(\d+)\s+0\s+R")


def parse_objects(data):
    objects = {}
    for m in OBJ_RE.finditer(data):
        num = int(m.group(1))
        body = m.group(2)
        idx = body.find(b"\nstream")
        if idx != -1:
            head, tail = body[:idx], body[idx:]
        else:
            head, tail = body, b""
        objects[num] = (head, tail)
    return objects


def stream_bytes(objects, num):
    head, tail = objects[num]
    m = re.search(rb"stream\r?\n(.*?)endstream", tail, re.DOTALL)
    return m.group(1) if m else None


def get_indirect_refs(head):
    return [int(m.group(1)) for m in REF_RE.finditer(head)]


def validate(path):
    with open(path, "rb") as f:
        data = f.read()
    errors = []

    # 1. startxref -> xref table
    m = re.search(rb"startxref\r?\n(\d+)", data)
    if not m:
        errors.append("no startxref")
        return errors
    xref_offset = int(m.group(1))
    if data[xref_offset:xref_offset + 4] != b"xref":
        errors.append(f"startxref {xref_offset} does not point to 'xref'")

    # 2. parse trailer /Root /Size
    trailer_m = re.search(rb"trailer\r?\n(<<.*?>>)", data, re.DOTALL)
    trailer = trailer_m.group(1) if trailer_m else b""
    root_m = re.search(rb"/Root\s+(\d+)\s+0\s+R", trailer)
    size_m = re.search(rb"/Size\s+(\d+)", trailer)
    root = int(root_m.group(1)) if root_m else None
    size = int(size_m.group(1)) if size_m else None
    print(f"trailer: /Root {root} /Size {size}")

    # 3. parse xref entries
    xref_section = data[xref_offset:data.find(b"trailer", xref_offset)]
    entries = {}
    for line_m in re.finditer(rb"(\d{10}) (\d{5}) ([nf])", xref_section):
        pass  # covered below via structured parse
    # structured parse of the subsection
    sub_m = re.search(rb"xref\r?\n(\d+) (\d+)\r?\n", xref_section)
    if sub_m:
        start, count = int(sub_m.group(1)), int(sub_m.group(2))
        entry_lines = re.findall(rb"(\d{10}) (\d{5}) ([nf]) \r?\n", xref_section[sub_m.end():])
        for i, (off, gen, kind) in enumerate(entry_lines[:count]):
            entries[start + i] = (int(off), int(gen), kind.decode())
    print(f"xref entries parsed: {len(entries)}")

    # 4. verify each in-use entry points at 'N 0 obj'
    objects = parse_objects(data)
    for num, (off, gen, kind) in entries.items():
        if kind == "n" and num != 0:
            line = data[off:off + 32]
            if not re.match(rb"^\d+ 0 obj\b", line):
                errors.append(f"xref entry {num} offset {off} not at object start: {line[:20]!r}")

    # 5. walk page tree from catalog
    if root is None or root not in objects:
        errors.append(f"catalog object {root} missing")
        return errors
    catalog_head = objects[root][0]
    pm = re.search(rb"/Pages\s+(\d+)\s+0\s+R", catalog_head)
    if not pm:
        errors.append("catalog has no /Pages")
        return errors

    pages_seen = set()
    page_nums = []
    stack = [int(pm.group(1))]
    while stack:
        node = stack.pop()
        if node in pages_seen:
            continue
        pages_seen.add(node)
        head, tail = objects[node]
        if re.search(rb"/Type\s*/Pages\b", head):
            for kid in re.findall(rb"/Kids\s*\[\s*([^\]]*)\]", head):
                for k in re.findall(rb"(\d+)\s+0\s+R", kid):
                    stack.append(int(k))
        elif re.search(rb"/Type\s*/Page\b", head):
            page_nums.append(node)
        else:
            errors.append(f"node {node} is neither Page nor Pages: {head[:60]!r}")
    print(f"pages found via tree walk: {sorted(page_nums)}")
    if len(page_nums) != 2:
        errors.append(f"expected 2 pages, found {len(page_nums)}")

    # 6. all indirect refs in object heads must resolve
    for num, (head, _t) in objects.items():
        for ref in get_indirect_refs(head):
            if ref not in objects:
                errors.append(f"object {num} references missing object {ref}")

    # 7. streams must be byte-identical to originals
    with open("report_part1.pdf", "rb") as f:
        orig1 = parse_objects(f.read())
    with open("report_part2.pdf", "rb") as f:
        orig2 = parse_objects(f.read())
    # find content stream objects in originals
    for label, orig, offset in [("part1", orig1, 0), ("part2", orig2, 8)]:
        for num, (head, _t) in orig.items():
            if re.search(rb"/Type\s*/Page\b", head) and not re.search(rb"/Type\s*/Pages\b", head):
                cm = re.search(rb"/Contents\s+(\d+)\s+0\s+R", head)
                if cm:
                    orig_stream = stream_bytes(orig, int(cm.group(1)))
                    merged_stream = stream_bytes(objects, offset + int(cm.group(1)))
                    status = "MATCH" if orig_stream == merged_stream else "MISMATCH"
                    print(f"{label} content stream (obj {offset + int(cm.group(1))}): {status}")
                    if orig_stream != merged_stream:
                        errors.append(f"{label} stream corrupted")

    if errors:
        print("VALIDATION FAILED:")
        for e in errors:
            print(" -", e)
        return False
    print("VALIDATION PASSED: xref OK, 2 pages, all refs resolve, streams intact")
    return True


if __name__ == "__main__":
    ok = validate("combined_report.pdf")
    print("RESULT:", "PASS" if ok else "FAIL")
    raise SystemExit(0 if ok else 1)

